import React, { type FC } from 'react'
import { useTranslation } from '@markflowy/i18n'
import type { NodeRendererProps } from 'react-arborist'
import { toast } from 'zens'
import { AppContext } from '../../contexts/AppContext'
import { useFileSystem } from '../../contexts/FileSystemContext'
import { useFileTree } from '../../contexts/FileTreeContext'
import type { IFile } from '../../types/file'
import {
  captureFileMutationTarget,
  collectFileMutationProtection,
  getCurrentFileMutationNode,
} from './file-mutation'
import { moveFileNode } from './file-operator'
import { copyFileTreeNode, getCopyParentPath } from './file-copy'
import NewFileInput from './NewFileInput'
import { hasRenameConflict } from './rename-conflict'
import { EmptyFolderStatus, LoadingIcon, NodeContainer } from './styles'
import { SimpleTree } from './types'
import { getFileNameFromPath } from './verify-file-name'
import type { FileTreeOpenOptions } from './FileTree'

export interface FileNodeComponentProps extends NodeRendererProps<IFile> {
  getCurrentFolderData: () => IFile[]
  canInsertIntoDirectory?: (directory: IFile) => boolean
  setFolderData: (data: IFile[]) => void
  refreshDirectory?: (directory: IFile, previousDirectoryPath?: string) => Promise<void>
  onFocusActiveFile?: (id: string) => Promise<void> | void
  onOpen?: (file: IFile, options: FileTreeOpenOptions) => void
  isRoot?: boolean
  onShowConfirm: (params: { title: string; onConfirm: () => void }) => void
  /** Let the host present a product-specific deletion confirmation. */
  onRequestDelete?: (request: FileTreeDeletionRequest) => void
  onShowInputConfirm?: (params: {
    title: string
    confirmText?: string
    cancelText?: string
    onConfirm: () => void
    onClose: () => void
  }) => void
  onShowContextMenu: (params: { x: number; y: number; items: ContextMenuItem[] }) => void
  getFileObject: (id: string) => IFile | undefined
  getFileObjectByPath: (path: string) => IFile | undefined
  setFileObject?: (id: string, file: IFile) => void
  setFileObjectByPath?: (path: string, file: IFile) => void
  deletePathEntry?: (path: string) => void
  getFileIdsByPathPrefix?: (path: string) => string[]
  moveFileObjectsByPathPrefix?: (oldRootPath: string, newRootPath: string) => void
  deleteFileObjectsByPathPrefix?: (rootPath: string) => void
  createFile?: (opt?: Partial<IFile>) => IFile
  updateFile?: (file: IFile) => IFile
  fileTreeHandler?: {
    rootTree: any
    updateTreeView: ((params: { data: IFile[] }) => void) | undefined
    clearLoadedDirsCache?: () => void
  }
  disableFileOperations?: boolean
  iconButtonComponent?: FC<any>
  renderNodeIcon?: FileTreeNodeIconRenderer
  /** Optional marker drawn before the type icon, inside the row. */
  renderNodePrefix?: (file: IFile) => React.ReactNode
  /** How a row is named; hosts that hide the extension pass their own. */
  renderNodeName?: (file: IFile) => string
  rootActions?: React.ReactNode
  isLoading?: boolean
  isEmpty?: boolean
  isStickyRoot?: boolean
  isRootSuppressed?: boolean
}

export type FileTreeNodeIconRenderer = (
  file: IFile,
  state: { isLoading: boolean; isOpen: boolean },
) => React.ReactNode

export interface FileTreeDeletionRequest {
  /** Snapshot of the requested entry, captured before the confirmation opens. */
  file: IFile
  mode: 'permanent' | 'trash'
  onConfirm: () => Promise<void>
}

export interface ContextMenuItem {
  label: string
  value: string
  handler?: () => void
  children?: ContextMenuItem[]
}

export type FileTreePathCopyType = 'absolute' | 'relative'

export function createPathCopyMenuItems(
  path: string,
  onCopyPath: (path: string, type: FileTreePathCopyType) => Promise<void> | void,
  labels: { absolute: string; relative: string },
): ContextMenuItem[] {
  return [
    {
      value: 'copy_path',
      label: labels.absolute,
      handler: () => void onCopyPath(path, 'absolute'),
    },
    {
      value: 'copy_relative_path',
      label: labels.relative,
      handler: () => void onCopyPath(path, 'relative'),
    },
  ]
}

export async function copyFileTreePath({
  path,
  type,
  rootPath,
  copyText,
  getRelativePath,
}: {
  path: string
  type: FileTreePathCopyType
  rootPath?: string
  copyText: (text: string) => Promise<void> | void
  getRelativePath: (path: string, rootPath: string) => Promise<string>
}) {
  const text = type === 'relative' && rootPath ? await getRelativePath(path, rootPath) : path
  await copyText(text)
}

export function collapseAllFileTreeFolders(
  tree: Pick<NodeRendererProps<IFile>['tree'], 'closeAll'>,
  workspaceRoot: Pick<NodeRendererProps<IFile>['node'], 'open'>,
) {
  tree.closeAll()
  workspaceRoot.open()
}

const extFileIconClassMap: Record<string, string> = {
  md: 'ri-markdown-line',
  markdown: 'ri-markdown-line',
  json: 'ri-file-code-line',
}

const getFileIconClass = (file: IFile) => {
  const ext = file.ext
  if (ext && extFileIconClassMap[ext]) {
    return extFileIconClassMap[ext]
  }
  return 'ri-file-line'
}

function FileNode({
  style,
  node,
  dragHandle,
  tree,
  getCurrentFolderData,
  canInsertIntoDirectory = (directory) => Boolean(directory.children?.length),
  setFolderData,
  refreshDirectory,
  onFocusActiveFile,
  onOpen,
  isRoot = false,
  onShowConfirm,
  onRequestDelete,
  onShowInputConfirm,
  onShowContextMenu,
  getFileObject,
  getFileObjectByPath,
  createFile,
  updateFile,
  deletePathEntry,
  getFileIdsByPathPrefix,
  setFileObject,
  setFileObjectByPath,
  moveFileObjectsByPathPrefix,
  deleteFileObjectsByPathPrefix,
  fileTreeHandler,
  disableFileOperations = false,
  iconButtonComponent: IconButton,
  renderNodeIcon,
  renderNodeName,
  renderNodePrefix,
  rootActions,
  isLoading = false,
  isEmpty = false,
  isStickyRoot = false,
  isRootSuppressed = false,
}: FileNodeComponentProps) {
  const { t } = useTranslation()
  const appContext = React.useContext(AppContext)
  const { deleteNode, trashNode, activeId, refreshFolder, getRootPath } = useFileTree()
  const {
    runFileMutation,
    renameFile,
    copyFile,
    selectCopyDirectory,
    createFolder,
    writeFile,
    fileExists,
    getMdRelativePath,
    pathsReferToSameDirectoryEntry,
    revealInFolder,
  } = useFileSystem()

  const requestDeletion = (mode: FileTreeDeletionRequest['mode']) => {
    const target = captureFileMutationTarget(node.data)
    const root = getCurrentFolderData()[0]
    const workspace = root ? captureFileMutationTarget(root) : undefined
    if (
      !target ||
      !workspace ||
      (target.id === workspace.id && target.path === workspace.path)
    ) return
    const file: IFile = {
      id: target.id,
      path: target.path,
      name: node.data.name,
      kind: node.data.kind,
      ext: node.data.ext,
    }
    const isCurrentWorkspace = (data: IFile[]) =>
      data[0]?.id === workspace.id && data[0]?.path === workspace.path

    const onConfirm = async () => {
      try {
        await runFileMutation(async (lease) => {
          const currentData = getCurrentFolderData()
          if (!isCurrentWorkspace(currentData)) return
          if (currentData[0]?.id === target.id && currentData[0]?.path === target.path) return
          const mutationTree = new SimpleTree(currentData)
          const currentNode = getCurrentFileMutationNode(mutationTree, getFileObject, target)
          if (!currentNode) return
          const protection = collectFileMutationProtection(
            [currentNode.data],
            getFileObject,
            getFileIdsByPathPrefix,
          )
          lease.protectFileIds(protection.fileIds)
          lease.protectPaths(protection.paths)

          await (mode === 'permanent' ? deleteNode : trashNode)(currentNode.data)

          // Directory reads can update other branches during the backend call.
          // Apply the successful removal to the latest tree instead of the snapshot.
          const latestData = getCurrentFolderData()
          if (!isCurrentWorkspace(latestData)) return
          const currentTree = new SimpleTree(latestData)
          if (!getCurrentFileMutationNode(currentTree, getFileObject, target)) return
          currentTree.drop({ id: target.id })
          if (deleteFileObjectsByPathPrefix) {
            deleteFileObjectsByPathPrefix(target.path)
          } else {
            deletePathEntry?.(target.path)
          }
          setFolderData(currentTree.data)
        })
      } catch (error) {
        toast.error(error instanceof Error ? error.message : String(error))
      }
    }

    if (onRequestDelete) {
      onRequestDelete({ file, mode, onConfirm })
    } else {
      onShowConfirm({
        title: mode === 'permanent'
          ? `Are you sure you want to delete ${file.name}?`
          : `Are you sure you want to move ${file.name} to trash?`,
        onConfirm,
      })
    }
  }

  const isPending = [
    'pending_new_file',
    'pending_new_folder',
    'pending_edit_folder',
    'pending_edit_file',
  ].includes(node.data.kind)

  const inputType =
    node.data.kind === 'pending_new_folder' || node.data.kind === 'pending_edit_folder'
      ? 'dir'
      : 'file'
  const isUpdate =
    node.data.kind === 'pending_edit_folder' || node.data.kind === 'pending_edit_file'

  const createFileHandler = async (file: IFile) => {
    const pendingId = node.id
    const pendingKind = node.data.kind
    const parentTarget = node.parent ? captureFileMutationTarget(node.parent.data) : undefined
    if (!file.path || !parentTarget) return

    await runFileMutation(async () => {
      const mutationTree = new SimpleTree(getCurrentFolderData())
      const pendingNode = mutationTree.find(pendingId)
      const currentParent = getCurrentFileMutationNode(mutationTree, getFileObject, parentTarget)
      if (!pendingNode || pendingNode.data.kind !== pendingKind || !currentParent) return

      if (await fileExists(file.path!)) {
        toast.error('File already exists')
        return
      }

      if (inputType === 'dir') {
        await createFolder(file.path!)
      } else {
        await writeFile(file.path!, '')
      }

      const targetFile = createFile
        ? createFile({
            path: file.path,
            name: file.name,
            content: '',
            id: pendingId,
            kind: file.kind,
          })
        : { ...file, content: '' }

      mutationTree.update({
        id: pendingId,
        changes: { ...pendingNode.data, ...targetFile },
      })
      setFolderData(mutationTree.data)
      if (targetFile.kind === 'file') onOpen?.(targetFile, { mode: 'permanent' })
      await refreshDirectory?.(currentParent.data)
    })
  }

  const renameFileHandler = async (file: IFile) => {
    const target = captureFileMutationTarget(node.data)
    const nextPath = file.path
    if (!target || !nextPath) return

    await runFileMutation(async (lease) => {
      const mutationTree = new SimpleTree(getCurrentFolderData())
      const currentNode = getCurrentFileMutationNode(mutationTree, getFileObject, target)
      if (!currentNode) return
      const protection = collectFileMutationProtection(
        [currentNode.data],
        getFileObject,
        getFileIdsByPathPrefix,
      )
      lease.protectFileIds(protection.fileIds)
      lease.protectPaths(protection.paths)
      lease.protectPaths([nextPath])

      if (
        await hasRenameConflict({
          currentPath: target.path,
          candidatePath: nextPath,
          fileExists,
          pathsReferToSameDirectoryEntry,
        })
      ) {
        toast.error('File already exists')
        return
      }

      const moveFileInfo = await renameFile(target.path, nextPath)

      moveFileNode(
        mutationTree,
        moveFileInfo,
        getFileObject,
        getFileObjectByPath,
        deletePathEntry,
        setFileObjectByPath,
        setFileObject,
        moveFileObjectsByPathPrefix,
        deleteFileObjectsByPathPrefix,
      )
      if (!refreshDirectory) fileTreeHandler?.clearLoadedDirsCache?.()

      if (updateFile) {
        updateFile({
          path: nextPath,
          name: file.name,
          id: target.id,
          kind: file.kind,
        })
      }

      mutationTree.update({
        id: target.id,
        changes: { kind: file.kind, name: file.name },
      })
      setFolderData(mutationTree.data)
      if (currentNode.parent) {
        await refreshDirectory?.(
          currentNode.parent.data,
          file.kind === 'dir' ? target.path : undefined,
        )
      }
    })
  }

  const handleContextMenu = (e: React.MouseEvent) => {
    e.stopPropagation()
    e.preventDefault()
    if (disableFileOperations) return

    const items: ContextMenuItem[] = []

    if (node.parent) {
      items.push({
        label: t('contextmenu.explorer.new'),
        value: 'new',
        children: [
          {
            label: t('contextmenu.explorer.add_file'),
            value: 'new_file',
            handler: () => {
              if (node.parent) {
                const mutationTree = new SimpleTree(getCurrentFolderData())
                const parentData = node.isInternal ? node.data : node.parent.data
                const parentTarget = captureFileMutationTarget(parentData)
                if (
                  !parentTarget ||
                  !getCurrentFileMutationNode(mutationTree, getFileObject, parentTarget)
                ) {
                  return
                }

                const data = {
                  id: `pending-${Date.now()}`,
                  name: '',
                  kind: 'pending_new_file',
                } as IFile
                if (node.isInternal) {
                  node.open()
                }

                mutationTree.create({
                  parentId: parentTarget.id,
                  data,
                })
                setFolderData(mutationTree.data)
              }
            },
          },
          {
            label: t('contextmenu.explorer.add_folder'),
            value: 'new_folder',
            handler: () => {
              if (node.parent) {
                const mutationTree = new SimpleTree(getCurrentFolderData())
                const parentData = node.isInternal ? node.data : node.parent.data
                const parentTarget = captureFileMutationTarget(parentData)
                if (
                  !parentTarget ||
                  !getCurrentFileMutationNode(mutationTree, getFileObject, parentTarget)
                ) {
                  return
                }

                const data = {
                  id: `pending-${Date.now()}`,
                  name: '',
                  kind: 'pending_new_folder',
                  children: [],
                } as IFile
                if (node.isInternal) {
                  node.open()
                }

                mutationTree.create({
                  parentId: parentTarget.id,
                  data,
                })
                setFolderData(mutationTree.data)
              }
            },
          },
        ],
      })
    }

    if (node.data.kind === 'dir' || node.data.ext === 'md') {
      items.push({
        label: t('contextmenu.explorer.rename'),
        value: 'rename',
        handler: () => {
          const target = captureFileMutationTarget(node.data)
          if (node.parent && target) {
            const mutationTree = new SimpleTree(getCurrentFolderData())
            const currentNode = getCurrentFileMutationNode(mutationTree, getFileObject, target)
            if (!currentNode) return

            mutationTree.update({
              id: target.id,
              changes: {
                kind: currentNode.data.kind === 'dir' ? 'pending_edit_folder' : 'pending_edit_file',
              },
            })
            setFolderData(mutationTree.data)
          }
        },
      })
    }

    if (node.data.kind === 'file') {
      const source = captureFileMutationTarget(node.data)
      const parent = node.parent ? captureFileMutationTarget(node.parent.data) : undefined
      const rootData = getCurrentFolderData()[0]
      const root = rootData ? captureFileMutationTarget(rootData) : undefined
      const copy = async (mode: 'duplicate' | 'copy-to') => {
        if (!source || !parent || !root) return
        try {
          const copiedPath = await copyFileTreeNode({
            source,
            parent,
            root,
            mode,
            fileSystem: { runFileMutation, copyFile, selectCopyDirectory },
            getCurrentFolderData,
            setFolderData,
            getFileObject,
            getFileObjectByPath,
            getFileIdsByPathPrefix,
            createFile,
            canInsertIntoDirectory,
            refreshDirectory,
          })
          if (copiedPath) {
            toast.success(
              t(
                mode === 'duplicate'
                  ? 'contextmenu.explorer.duplicate_success'
                  : 'contextmenu.explorer.copy_to_success',
                { name: getFileNameFromPath(copiedPath), folder: getCopyParentPath(copiedPath) },
              ),
            )
          }
        } catch (error) {
          toast.error(
            t('contextmenu.explorer.copy_failed', {
              reason: error instanceof Error ? error.message : String(error),
            }),
          )
        }
      }

      items.push({
        value: 'duplicate_file',
        label: t('contextmenu.explorer.duplicate_file'),
        handler: () => void copy('duplicate'),
      })
      if (selectCopyDirectory) {
        items.push({
          value: 'copy_to',
          label: t('contextmenu.explorer.copy_to'),
          handler: () => void copy('copy-to'),
        })
      }
    }

    const alreadyEncrypted =
      node.data.kind === 'file' && node.data.path
        ? Boolean(appContext?.isNoteEncrypted?.(node.data.path))
        : false

    if (node.data.path && appContext?.encryptNote && !alreadyEncrypted) {
      const isFolder = node.data.kind === 'dir'
      items.push({
        value: isFolder ? 'encrypt_folder' : 'encrypt_note',
        label: isFolder
          ? t('contextmenu.explorer.encrypt_folder')
          : t('contextmenu.explorer.encrypt_note'),
        handler: () =>
          void (isFolder
            ? appContext?.encryptNotesInFolder?.(node.data.path!)
            : appContext?.encryptNote?.(node.data.path!)),
      })
    }

    if (node.data.kind === 'file' && node.data.path && appContext?.toggleBookmarkNote) {
      items.push({
        value: 'bookmark_note',
        label: t('bookmarks.add'),
        handler: () => void appContext?.toggleBookmarkNote?.(node.data.path!, node.data.name),
      })
    }

    if (node.data.path && appContext?.copyText) {
      const copyText = appContext.copyText
      items.push({
        value: 'copy_paths',
        label: t('contextmenu.explorer.copy_path'),
        children: createPathCopyMenuItems(
          node.data.path,
          async (path, type) => {
            try {
              await copyFileTreePath({
                path,
                type,
                rootPath: getRootPath(),
                copyText,
                getRelativePath: getMdRelativePath,
              })
            } catch (error) {
              toast.error(error instanceof Error ? error.message : String(error))
            }
          },
          {
            absolute: t('contextmenu.explorer.absolute_path'),
            relative: t('contextmenu.explorer.relative_path'),
          },
        ),
      })
    }

    if (!isRoot) {
      items.push({
        value: node.data.kind === 'dir' ? 'delete_folder' : 'delete_file',
        label:
          node.data.kind === 'dir'
            ? t('contextmenu.explorer.delete_folder')
            : t('contextmenu.explorer.delete_file'),
        handler: () => requestDeletion('permanent'),
      })

      items.push({
        value: 'trash',
        label: t('contextmenu.explorer.moveto_trash'),
        handler: () => requestDeletion('trash'),
      })
    }

    if (revealInFolder) {
      items.push({
        value: 'show_in_folder',
        label: t('contextmenu.explorer.show_in_folder'),
        handler: async () => {
          try {
            const exists = await fileExists(node.data.path!)
            if (!exists || !node.data.path) {
              toast.error('File not found')
              return
            }
            await revealInFolder(node.data.path)
          } catch (error) {
            console.error('Failed to show in folder:', error)
          }
        },
      })
    }

    onShowContextMenu({
      x: e.clientX,
      y: e.clientY,
      items,
    })
  }

  const isDropHighlighted = !!(
    tree.dragDestinationParent?.isAncestorOf(node) &&
    tree.dragDestinationParent?.id !== tree.dragNode?.parent?.id
  )
  const isSelected = activeId === node.id

  const renderPendingEntry = () => (
    <>
      <span aria-hidden='true' className='file-icon mf-file-tree-icon'>
        {renderNodeIcon ? (
          renderNodeIcon(
            {
              ...node.data,
              kind: inputType,
              ext: node.data.ext ?? (inputType === 'file' ? 'md' : undefined),
            },
            { isLoading: false, isOpen: false },
          )
        ) : (
          <i className={inputType === 'dir' ? 'ri-folder-3-fill' : getFileIconClass(node.data)} />
        )}
      </span>
      <NewFileInput
        key={node.id}
        aria-label={t(
          isUpdate
            ? 'contextmenu.explorer.rename'
            : inputType === 'dir'
              ? 'contextmenu.explorer.add_folder'
              : 'contextmenu.explorer.add_file',
        )}
        className='mf-file-tree-name-input'
        fileNode={node.data}
        inputType={inputType}
        parentNode={node.parent?.data}
        onCreate={async (file) => {
          if (isUpdate) {
            await renameFileHandler(file)
          } else {
            await createFileHandler(file)
          }
        }}
        onCancel={(fileInfo) => {
          const cancelInput = () => {
            const mutationTree = new SimpleTree(getCurrentFolderData())
            const pendingNode = mutationTree.find(node.id)
            if (!pendingNode) return

            if (isUpdate) {
              mutationTree.update({
                id: node.id,
                changes: {
                  kind: pendingNode.data.kind === 'pending_edit_folder' ? 'dir' : 'file',
                },
              })
            } else {
              mutationTree.drop({ id: node.id })
            }

            setFolderData(mutationTree.data)
          }

          if (!fileInfo) {
            cancelInput()
            return
          }

          if (onShowInputConfirm) {
            onShowInputConfirm({
              title: 'Save changes?',
              confirmText: 'Save',
              cancelText: 'Discard',
              onConfirm: async () => {
                if (isUpdate) {
                  await renameFileHandler(fileInfo)
                } else {
                  await createFileHandler(fileInfo)
                }
              },
              onClose: () => {
                cancelInput()
              },
            })
          } else {
            cancelInput()
          }
        }}
      />
    </>
  )

  const renderEntryContent = () => (
    <div
      style={{
        display: 'flex',
        width: '100%',
        justifyContent: 'space-between',
        alignItems: 'center',
      }}
    >
      <div
        aria-hidden={isStickyRoot || undefined}
        style={{
          flex: 1,
          display: 'flex',
          alignItems: 'center',
          overflow: 'hidden',
          minWidth: 0,
        }}
      >
        {renderNodePrefix ? (
          <span className='mf-file-tree-prefix'>{renderNodePrefix(node.data)}</span>
        ) : null}
        {renderNodeIcon ? (
          <span
            aria-label={isLoading ? `${t('common.fetching')} ${node.data.name}` : undefined}
            className='file-icon mf-file-tree-icon'
            role={isLoading ? 'status' : undefined}
          >
            {renderNodeIcon(node.data, { isLoading, isOpen: node.isOpen })}
          </span>
        ) : node.data?.kind === 'dir' ? (
          isLoading ? (
            <LoadingIcon
              className='ri-loader-4-line file-icon'
              role='status'
              aria-label={`${t('common.fetching')} ${node.data.name}`}
            />
          ) : (
            <i className={`${node.isOpen ? 'ri-folder-5-fill' : 'ri-folder-3-fill'} file-icon`} />
          )
        ) : (
          <i className={`${getFileIconClass(node.data)} file-icon`} />
        )}
        <span
          style={{
            whiteSpace: 'nowrap',
            overflow: 'hidden',
            textOverflow: 'ellipsis',
          }}
        >
          {renderNodeName ? renderNodeName(node.data) : node.data.name}
        </span>
        {isEmpty ? (
          <EmptyFolderStatus role='status'>{t('file.emptyFolder')}</EmptyFolderStatus>
        ) : null}
      </div>

      {isRoot && (IconButton || rootActions) ? (
        <div style={{ display: 'flex', gap: '2px' }}>
          {rootActions}
          {IconButton ? (
            <>
              <IconButton
                size='small'
                rounded='smooth'
                icon={'ri-refresh-line'}
                onClick={async (e?: React.MouseEvent) => {
                  e?.stopPropagation()
                  e?.preventDefault()
                  await refreshFolder()
                }}
                tooltipProps={{ title: 'Refresh' }}
              />
              <IconButton
                size='small'
                rounded='smooth'
                icon={'ri-focus-3-line'}
                onClick={(e?: React.MouseEvent) => {
                  e?.stopPropagation()
                  e?.preventDefault()
                  if (activeId) {
                    if (onFocusActiveFile) void onFocusActiveFile(activeId)
                    else tree.select(activeId, { align: 'center' })
                  }
                }}
                tooltipProps={{ title: 'Focus Active File' }}
              />
              <IconButton
                size='small'
                rounded='smooth'
                icon={'ri-collapse-vertical-fill'}
                onClick={(e?: React.MouseEvent) => {
                  e?.stopPropagation()
                  e?.preventDefault()
                  collapseAllFileTreeFolders(tree, node)
                }}
                tooltipProps={{ title: 'Collapse All' }}
              />
            </>
          ) : null}
        </div>
      ) : null}
    </div>
  )

  return (
    <NodeContainer
      style={style}
      data-mf-file-tree-drop-highlight={isDropHighlighted || undefined}
      data-mf-file-tree-node=''
      data-mf-file-tree-editing={isPending || undefined}
      data-mf-file-tree-root={isRoot || undefined}
      data-mf-file-tree-sticky-root={isStickyRoot || undefined}
      data-mf-file-tree-root-suppressed={isRootSuppressed || undefined}
      aria-hidden={isRootSuppressed || undefined}
      inert={isRootSuppressed || undefined}
      highlight={isDropHighlighted}
      selected={isSelected}
      aria-busy={isLoading || undefined}
      onContextMenu={handleContextMenu}
      onClick={(e) => {
        if (isPending) {
          e.stopPropagation()
          return
        }
        if (e.shiftKey) {
          return
        }
        if (node.data.kind === 'dir') {
          node.toggle()
        }
      }}
      onMouseUp={(e) => {
        if (isPending) {
          e.stopPropagation()
        }
      }}
      ref={isPending ? null : dragHandle}
    >
      <div className='mf-file-tree-row'>
        <div className='indentLines'>
          {Array.from({ length: node.level }, (_, level) => `indent-${level + 1}`).map((key) => {
            return <div key={key}></div>
          })}
        </div>
        {isPending ? renderPendingEntry() : renderEntryContent()}
      </div>
    </NodeContainer>
  )
}

export default FileNode
