import React, {
  createContext,
  memo,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type FC,
} from 'react'
import { Tree } from 'react-arborist'
import type { NodeRendererProps, RowRendererProps, TreeApi } from 'react-arborist'
import type { TreeProps } from 'react-arborist/dist/module/types/tree-props'
import type { MoveFileInfo } from '../../contexts/FileSystemContext'
import { useFileSystem } from '../../contexts/FileSystemContext'
import { useFileTree } from '../../contexts/FileTreeContext'
import type { IFile } from '../../types/file'
import FileNode from './FileNode'
import type {
  ContextMenuItem,
  FileNodeComponentProps,
  FileTreeDeletionRequest,
  FileTreeNodeIconRenderer,
} from './FileNode'
import {
  captureFileMutationTarget,
  collectFileMutationProtection,
  getCurrentFileMutationNode,
  getCurrentFileMutationNodeInRoot,
  getCurrentFileMutationNodes,
} from './file-mutation'
import { mergeDirectoryChildren, moveFileNode } from './file-operator'
import { FileTreeStickyRoot, FileTreeStickyViewport } from './styles'
import { SimpleTree } from './types'

const DEFAULT_FILE_TREE_INDENT_SIZE = 16
const DEFAULT_FILE_TREE_ROW_HEIGHT = 24

function fileTreePathKey(path: string) {
  const windows = /^[a-z]:[\\/]/i.test(path) || path.startsWith('\\\\')
  const normalized = windows ? path.replace(/\\/g, '/').toLowerCase() : path
  return normalized.replace(/\/+$/, '')
}

type FileTreeRowState = {
  onOpen?: FileTreeProps['onOpen']
  /** A click reuses the open tab; the middle button still asks for a new one. */
  openInSameTab?: boolean
  revealRoot?: () => void
  rootId?: string
  suppressRoot: boolean
}

const FileTreeRowStateContext = createContext<FileTreeRowState>({ suppressRoot: false })

const FileTreeNodeRendererContext = createContext<
  ((props: NodeRendererProps<IFile>) => React.ReactNode) | null
>(null)

// Arborist mounts its children as a component. Keep that component type stable
// while host props and directory-loading state change, preserving inline edits.
function FileTreeNodeRenderer(props: NodeRendererProps<IFile>) {
  const renderNode = useContext(FileTreeNodeRendererContext)
  return renderNode?.(props)
}

export interface FileTreeProps {
  data: IFile[]
  /** Optional sibling display order. Does not mutate backing nodes or their child arrays. */
  compareNodes?: (left: IFile, right: IFile) => number
  /** Additional host actions beside the workspace root's existing controls. */
  rootActions?: React.ReactNode
  /** Persistent directory paths supplied by the host; IDs may change between sessions. */
  expandedPaths?: readonly string[]
  onExpandedPathsChange?: (paths: string[]) => void
  onSelect?: (file: IFile) => void
  /** User opening intent, independent of programmatic selection and reveal. */
  onOpen?: (file: IFile, options: FileTreeOpenOptions) => void
  /**
   * A plain click replaces the note already open in the tab, and the middle button opens a new
   * tab. Off by default: each note keeps its own tab.
   */
  openInSameTab?: boolean
  dndRootElement?: Node | null
  disableDrag?: boolean
  /** Hide tree operations when the backing adapter only supports reading existing files. */
  disableFileOperations?: boolean
  fillFlexParentComponent: FC<{
    children: (dimens: { width: number; height: number }) => React.ReactNode
  }>
  onShowConfirm: (params: { title: string; onConfirm: () => void }) => void
  /** Let the host present a product-specific deletion confirmation. */
  onRequestDelete?: (request: FileTreeDeletionRequest) => void
  onShowInputConfirm?: (params: {
    title: string
    confirmText?: string
    cancelText?: string
    onConfirm: () => void
    onClose: () => void
  }) => void
  onShowContextMenu: (params: { x: number; y: number; items: ContextMenuItem[] }) => void
  getFileObject: (id: string) => IFile | undefined
  getFileObjectByPath: (path: string) => IFile | undefined
  setFileObject?: (id: string, file: IFile) => void
  setFileObjectByPath?: (path: string, file: IFile) => void
  deletePathEntry?: (path: string) => void
  getFileIdsByPathPrefix?: (path: string) => string[]
  moveFileObjectsByPathPrefix?: (oldRootPath: string, newRootPath: string) => void
  deleteFileObjectsByIds?: (fileIds: string[]) => void
  deleteFileObjectsByPathPrefix?: (rootPath: string) => void
  onBeforeReplace?: (
    path: string,
  ) =>
    | { allowed: boolean; targetIds: string[] }
    | Promise<{ allowed: boolean; targetIds: string[] }>
  createFile?: (opt?: Partial<IFile>) => IFile
  updateFile?: (file: IFile) => IFile
  iconButtonComponent?: React.ComponentType<any>
  /** Optional host renderer for product-specific file and folder icon systems. */
  renderNodeIcon?: FileTreeNodeIconRenderer
  renderNodePrefix?: (file: IFile) => React.ReactNode
  renderNodeName?: (file: IFile) => string
  /** Keep the first workspace folder visible above the virtualized rows while scrolling. */
  stickyRoot?: boolean
  /** Horizontal nesting step in pixels. */
  indentSize?: number
  /** Virtualized row height in pixels. */
  rowHeight?: number
}

export interface FileTreeOpenOptions {
  /** `replace` swaps the file shown in the active tab, used by "open notes in the same tab". */
  mode: 'preview' | 'permanent' | 'replace'
}

export function shouldShowFileTreeStickyRoot(scrollOffset: number) {
  return scrollOffset > 0
}

export const fileTreeHandler: {
  rootTree: undefined | TreeApi<IFile>
  updateTreeView: undefined | ((params: { data: IFile[] }) => void)
  clearLoadedDirsCache: undefined | (() => void)
} = {
  rootTree: undefined,
  updateTreeView: undefined,
  clearLoadedDirsCache: undefined,
}

const FileTree: FC<FileTreeProps> = (props) => {
  const {
    data,
    compareNodes,
    rootActions,
    expandedPaths,
    onExpandedPathsChange,
    onSelect,
    onOpen,
    openInSameTab,
    dndRootElement,
    disableDrag = false,
    disableFileOperations = false,
    fillFlexParentComponent: FillFlexParent,
    onShowConfirm,
    onRequestDelete,
    onShowInputConfirm,
    onShowContextMenu,
    getFileObject,
    getFileObjectByPath,
    setFileObject,
    setFileObjectByPath,
    deletePathEntry,
    getFileIdsByPathPrefix,
    moveFileObjectsByPathPrefix,
    deleteFileObjectsByIds,
    deleteFileObjectsByPathPrefix,
    onBeforeReplace,
    createFile,
    updateFile,
    iconButtonComponent,
    renderNodeIcon,
    renderNodePrefix,
    renderNodeName,
    stickyRoot = false,
    indentSize = DEFAULT_FILE_TREE_INDENT_SIZE,
    rowHeight = DEFAULT_FILE_TREE_ROW_HEIGHT,
  } = props

  const { activeId, setFolderDataPure } = useFileTree()
  const { runFileMutation, pathJoin, fileExists, moveFilesToTargetFolder, readSubdirectory } =
    useFileSystem()
  const tree = useMemo(() => new SimpleTree<IFile>(data), [data])
  const childrenAccessor = useCallback((file: IFile) => {
    if (!file.children) return null
    return compareNodes ? [...file.children].sort(compareNodes) : file.children
  }, [compareNodes])
  const treeRef = useRef<TreeApi<IFile> | null>(null)
  const [treeApi, setTreeApi] = useState<TreeApi<IFile> | null>()
  const loadedDirsRef = useRef<Set<string>>(new Set())
  const loadingDirsRef = useRef(new Map<string, Promise<void>>())
  const refreshDirsRef = useRef(new Set<string>())
  const loadedDirsCacheVersionRef = useRef(0)
  const focusRequestRef = useRef(0)
  const [loadingDirIds, setLoadingDirIds] = useState<ReadonlySet<string>>(() => new Set())
  const [loadedDirPaths, setLoadedDirPaths] = useState<ReadonlySet<string>>(() => new Set())
  const [showStickyRoot, setShowStickyRoot] = useState(false)
  // The pinned row lives outside react-arborist's provider, so a root toggle
  // needs one host render to read the NodeApi's updated open state.
  const [, setStickyRootRevision] = useState(0)
  const mountedRef = useRef(false)
  useEffect(() => {
    mountedRef.current = true
    return () => { mountedRef.current = false }
  }, [])
  const currentDataRef = useRef(data)
  currentDataRef.current = data
  const getCurrentFolderData = useCallback(
    () => mountedRef.current ? currentDataRef.current : [],
    [],
  )
  const requestDelete = useCallback((request: FileTreeDeletionRequest) => {
    onRequestDelete?.({
      ...request,
      onConfirm: async () => {
        if (!mountedRef.current) return
        await request.onConfirm()
      },
    })
  }, [onRequestDelete])
  const commitFolderData = useCallback((nextData: IFile[]) => {
    currentDataRef.current = nextData
    setFolderDataPure(nextData)
  }, [setFolderDataPure])
  const canInsertIntoDirectory = useCallback(
    (directory: IFile) =>
      Boolean(
        directory.children?.length ||
          (directory.path &&
            (loadedDirsRef.current.has(directory.path) ||
              loadingDirsRef.current.has(directory.path))),
      ),
    [],
  )
  const rootPath = data[0]?.path
  const rootId = data[0]?.id
  const openPathsRef = useRef(new Set(expandedPaths ?? (data[0]?.path ? [data[0].path] : [])))
  const initialOpenState = useMemo(
    () =>
      rootId
        ? {
            [rootId]: expandedPaths ? expandedPaths.includes(rootPath ?? '') : true,
          }
        : {},
    [rootId, rootPath, expandedPaths],
  )
  const revealRoot = useCallback(() => setShowStickyRoot(false), [])
  const fileTreeRowState = useMemo<FileTreeRowState>(
    () => ({
      onOpen,
      openInSameTab,
      revealRoot,
      rootId,
      suppressRoot: stickyRoot && showStickyRoot,
    }),
    [onOpen, openInSameTab, revealRoot, rootId, showStickyRoot, stickyRoot],
  )

  const handleScroll = useCallback<NonNullable<TreeProps<IFile>['onScroll']>>(
    ({ scrollOffset }) => {
      if (!stickyRoot) return

      const shouldShow = shouldShowFileTreeStickyRoot(scrollOffset)
      setShowStickyRoot((current) => (current === shouldShow ? current : shouldShow))
    },
    [stickyRoot],
  )

  const loadDirectory = async (nodeData: IFile) => {
    if (nodeData.kind !== 'dir' || !nodeData.path) return
    const workspaceRootId = data[0]?.id
    const target = captureFileMutationTarget(nodeData)
    if (!workspaceRootId || !target) return

    if (loadedDirsRef.current.has(target.path)) return
    const pending = loadingDirsRef.current.get(target.path)
    if (pending) return pending

    const refresh = refreshDirsRef.current.has(target.path)
    if (refresh || !nodeData.children || nodeData.children.length === 0) {
      const cacheVersion = loadedDirsCacheVersionRef.current
      setLoadingDirIds((current) => new Set(current).add(target.id))

      // Register before starting I/O so toggles and explicit reveal requests
      // share the same read and can both wait for its merged children.
      const loading = Promise.resolve().then(async () => {
        const isCurrent = () =>
          cacheVersion === loadedDirsCacheVersionRef.current &&
          loadingDirsRef.current.get(target.path) === loading
        try {
          const children = await readSubdirectory(target.path)
          if (!isCurrent()) return

          const currentTree = new SimpleTree(currentDataRef.current)
          const currentNode = getCurrentFileMutationNodeInRoot(
            currentTree,
            getFileObject,
            target,
            workspaceRootId,
          )
          if (!currentNode || currentNode.data.kind !== 'dir') return
          if (loadedDirsRef.current.has(target.path)) return

          loadedDirsRef.current.add(target.path)
          refreshDirsRef.current.delete(target.path)
          setLoadedDirPaths((current) => new Set(current).add(target.path))
          if (children.length > 0) {
            // Creating a node also opens its parent. Preserve drafts (and any
            // completed creations) inserted while this directory read was pending.
            const currentChildren = currentNode.data.children ?? []
            if (refresh) {
              const merged = mergeDirectoryChildren(currentChildren, children)
              if (merged === currentChildren) return
              currentNode.data.children = merged
            } else {
              const currentIds = new Set(currentChildren.map((child) => child.id))
              const currentPaths = new Set(currentChildren.map((child) => child.path).filter(Boolean))
              currentNode.data.children = [
                ...currentChildren,
                ...children.filter(
                  (child) =>
                    !currentIds.has(child.id) && (!child.path || !currentPaths.has(child.path)),
                ),
              ]
            }
            setFolderDataPure([...currentTree.data])
          }
        } catch (error) {
          console.error('Failed to load subdirectory:', error)
        } finally {
          if (isCurrent()) {
            loadingDirsRef.current.delete(target.path)
            setLoadingDirIds((current) => {
              if (!current.has(target.id)) return current

              const next = new Set(current)
              next.delete(target.id)
              return next
            })
          }
        }
      })
      loadingDirsRef.current.set(target.path, loading)
      await loading
    }
  }

  const refreshDirectory = async (directory: IFile, previousDirectoryPath?: string) => {
    if (!directory.path) return
    const invalidPaths = new Set([directory.path])
    if (previousDirectoryPath) {
      for (const path of new Set([
        ...loadedDirsRef.current,
        ...loadingDirsRef.current.keys(),
        ...refreshDirsRef.current,
      ])) {
        if (
          path === previousDirectoryPath ||
          path.startsWith(`${previousDirectoryPath}/`) ||
          path.startsWith(`${previousDirectoryPath}\\`)
        ) invalidPaths.add(path)
      }
    }
    // Retire reads started before the mutation. The loader checks the request
    // identity and workspace before merging, so late results cannot undo it.
    for (const path of invalidPaths) {
      loadedDirsRef.current.delete(path)
      loadingDirsRef.current.delete(path)
      refreshDirsRef.current.delete(path)
    }
    refreshDirsRef.current.add(directory.path)
    setLoadedDirPaths((current) => new Set([...current].filter((path) => !invalidPaths.has(path))))
    setLoadingDirIds((current) => new Set([...current].filter((id) => {
      const path = getFileObject(id)?.path
      return !path || !invalidPaths.has(path)
    })))
    await loadDirectory(directory)
  }

  const onToggle: TreeProps<IFile>['onToggle'] = async (id: string) => {
    if (stickyRoot && showStickyRoot && id === rootId) {
      setStickyRootRevision((current) => current + 1)
    }

    const node = new SimpleTree(currentDataRef.current).find(id)
    const nodeData = node?.data
    if (nodeData?.kind !== 'dir' || !nodeData.path) return
    const isOpen = Boolean(treeRef.current?.isOpen(id))
    if (openPathsRef.current.has(nodeData.path) !== isOpen) {
      if (isOpen) openPathsRef.current.add(nodeData.path)
      else openPathsRef.current.delete(nodeData.path)
      onExpandedPathsChange?.([...openPathsRef.current])
    }
    if (isOpen) await loadDirectory(nodeData)
  }

  useEffect(
    () => () => {
      focusRequestRef.current += 1
    },
    [activeId, rootId, rootPath],
  )

  const focusActiveFile = async (id: string) => {
    const api = treeRef.current
    if (!api) return
    const request = ++focusRequestRef.current
    const cacheVersion = loadedDirsCacheVersionRef.current
    const isCurrent = () =>
      request === focusRequestRef.current &&
      cacheVersion === loadedDirsCacheVersionRef.current &&
      currentDataRef.current[0]?.id === rootId &&
      currentDataRef.current[0]?.path === rootPath &&
      treeRef.current === api

    let target = new SimpleTree(currentDataRef.current).find(id)?.data
    const path = (target ?? getFileObject(id))?.path
    const pathKey = path ? fileTreePathKey(path) : undefined
    let children = currentDataRef.current
    while (!target && pathKey && isCurrent()) {
      const directory = children.find(
        (file) => file.kind === 'dir' && file.path && pathKey.startsWith(`${fileTreePathKey(file.path)}/`),
      )
      if (!directory) return
      api.open(directory.id)
      await loadDirectory(directory)
      if (!isCurrent()) return

      const currentDirectory = new SimpleTree(currentDataRef.current).find(directory.id)?.data
      if (!currentDirectory || currentDirectory.path !== directory.path) return
      children = currentDirectory.children ?? []
      target = children.find(
        (file) => file.id === id || (file.path && fileTreePathKey(file.path) === pathKey),
      )
    }
    if (!target || target.kind !== 'file' || !isCurrent()) return

    // Arborist opens loaded ancestors and waits until the virtual row exists.
    // Select afterwards so the host receives the current node, including files
    // that were absent from the tree when this command started.
    await api.scrollTo(target.id, 'center')
    if (isCurrent() && api.get(target.id)) api.select(target.id, { align: 'center' })
  }

  useEffect(
    () => () => {
      loadedDirsCacheVersionRef.current += 1
      loadingDirsRef.current.clear()
    },
    [],
  )

  const toggleRef = useRef(onToggle)
  toggleRef.current = onToggle
  useEffect(() => {
    // The sizing host may mount Tree after this component's first effect.
    // Restore as soon as its API is attached, before a click changes the paths.
    if (!expandedPaths || !treeApi) return
    const api = treeApi
    const desiredPaths = new Set(expandedPaths)
    openPathsRef.current = desiredPaths
    const restoreChildren = (nodes: IFile[]) => {
      for (const node of nodes) {
        if (node.kind !== 'dir' || !node.path || !desiredPaths.has(node.path)) continue
        if (!api.isOpen(node.id)) api.open(node.id)
        // Initial root state doesn't fire Arborist's onToggle. Reuse its lazy
        // loader, which also guards duplicate and stale directory responses.
        else void toggleRef.current?.(node.id)
        if (node.children) restoreChildren(node.children)
      }
    }
    restoreChildren(data)
  }, [data, expandedPaths, treeApi])

  const onMove: TreeProps<IFile>['onMove'] = async (args) => {
    if (disableFileOperations) return

    const _dragNodes = args.dragNodes.filter((node) => {
      return !args.dragIds.includes(node.parent?.id || '')
    })
    const _dragNode = _dragNodes[0]
    const parentNode = args.parentNode

    if (!_dragNode || !parentNode || _dragNode.parent?.id === parentNode.id) {
      return
    }
    const sourceTargets = _dragNodes.map((dragNode) => captureFileMutationTarget(dragNode.data))
    const parentTarget = captureFileMutationTarget(parentNode.data)
    if (sourceTargets.some((target) => !target) || !parentTarget) return

    const capturedSourceTargets = sourceTargets.filter(
      (target): target is NonNullable<typeof target> => Boolean(target),
    )
    const targetPaths = await Promise.all(
      _dragNodes.map((dragNode) => pathJoin(parentTarget.path, dragNode.data.name)),
    )
    const isExist = (await Promise.all(targetPaths.map(fileExists))).some(Boolean)

    const move = async (replace = false) => {
      await runFileMutation(async (lease) => {
        const initialData = getCurrentFolderData()
        const workspaceRootId = initialData[0]?.id
        let mutationTree = new SimpleTree(initialData)
        const currentParent = getCurrentFileMutationNode(mutationTree, getFileObject, parentTarget)
        const verifiedDragNodes = getCurrentFileMutationNodes(
          mutationTree,
          getFileObject,
          capturedSourceTargets,
        )
        if (!currentParent || !verifiedDragNodes) return
        if (verifiedDragNodes.some((dragNode) => dragNode.parent?.id === parentTarget.id)) return
        const sourceProtection = collectFileMutationProtection(
          verifiedDragNodes.map((dragNode) => dragNode.data),
          getFileObject,
          getFileIdsByPathPrefix,
        )
        lease.protectFileIds(sourceProtection.fileIds)
        lease.protectPaths(sourceProtection.paths)

        const currentTargetPaths = await Promise.all(
          verifiedDragNodes.map((dragNode) => pathJoin(parentTarget.path, dragNode.data.name)),
        )
        lease.protectPaths(currentTargetPaths)
        const existingTargetPaths = (
          await Promise.all(
            currentTargetPaths.map(async (path) => ({
              exists: await fileExists(path),
              path,
            })),
          )
        ).filter(({ exists }) => exists)

        if (!replace && existingTargetPaths.length > 0) {
          onShowConfirm({
            title: `Replace ${verifiedDragNodes[0].data.name}?`,
            onConfirm: () => void move(true),
          })
          return
        }

        const replacementIdsByPath = new Map<string, string[]>()
        if (replace && onBeforeReplace) {
          for (const { path } of existingTargetPaths) {
            const preflight = await onBeforeReplace(path)
            replacementIdsByPath.set(path, preflight.targetIds)
            lease.protectFileIds(preflight.targetIds)
            lease.protectPaths(
              preflight.targetIds
                .map((id) => getFileObject(id)?.path)
                .filter((candidatePath): candidatePath is string => !!candidatePath),
            )
            if (!preflight.allowed) return
          }
        }

        const res = await moveFilesToTargetFolder({
          files: capturedSourceTargets.map((target) => target.path),
          targetFolder: parentTarget.path,
          replaceExist: replace,
        })

        if (Array.isArray(res) && res.length > 0) {
          // Lazy reads and inline drafts can update the tree while the backend
          // move is pending, even though filesystem mutations are serialized.
          const latestData = getCurrentFolderData()
          if (latestData[0]?.id !== workspaceRootId) return
          if (latestData !== initialData) mutationTree = new SimpleTree(latestData)
          const destination = getCurrentFileMutationNode(mutationTree, getFileObject, parentTarget)
          if (!destination) return
          const successfulSourcePaths = new Set(
            res.filter((moveFileInfo) => !moveFileInfo.is_replaced).map(({ old_path }) => old_path),
          )
          const dragIds = capturedSourceTargets
            .filter((target) => successfulSourcePaths.has(target.path))
            .map((target) => target.id)

          res.forEach((moveFileInfo) => {
            moveFileNode(
              mutationTree,
              moveFileInfo as MoveFileInfo,
              getFileObject,
              getFileObjectByPath,
              deletePathEntry,
              setFileObjectByPath,
              setFileObject,
              moveFileObjectsByPathPrefix,
              deleteFileObjectsByPathPrefix,
              {
                deleteFileObjectsByIds,
                replacementIds: replacementIdsByPath.get(moveFileInfo.old_path),
              },
            )
          })

          for (const id of dragIds) {
            mutationTree.move({
              id,
              parentId: parentTarget.id,
              index: destination.children?.length ?? 0,
            })
          }

          // Retire pre-move reads only for affected directories. Unrelated empty
          // folders must keep their loaded status and should not be read again.
          const invalidPaths = new Set([parentTarget.path])
          const sourceParentPaths = new Set<string>()
          for (const node of verifiedDragNodes) {
            const sourceParent = node.parent?.data
            if (sourceParent?.path && loadingDirsRef.current.has(sourceParent.path)) {
              invalidPaths.add(sourceParent.path)
              sourceParentPaths.add(sourceParent.path)
            }
          }
          const movedFolders = res.filter((entry) => entry.is_folder).map((entry) => entry.old_path)
          if (movedFolders.length > 0) {
            for (const path of new Set([
              ...loadedDirsRef.current,
              ...loadingDirsRef.current.keys(),
              ...refreshDirsRef.current,
            ])) {
              if (movedFolders.some((oldPath) =>
                path === oldPath || path.startsWith(`${oldPath}/`) || path.startsWith(`${oldPath}\\`),
              )) invalidPaths.add(path)
            }
          }
          for (const path of invalidPaths) {
            loadedDirsRef.current.delete(path)
            loadingDirsRef.current.delete(path)
            refreshDirsRef.current.delete(path)
          }
          sourceParentPaths.forEach((path) => refreshDirsRef.current.add(path))
          refreshDirsRef.current.add(parentTarget.path)
          setLoadedDirPaths((current) => new Set([...current].filter((path) => !invalidPaths.has(path))))
          const movedIds = new Set(sourceProtection.fileIds)
          setLoadingDirIds((current) => new Set([...current].filter((id) => {
            const path = getFileObject(id)?.path
            return !movedIds.has(id) && (!path || !invalidPaths.has(path))
          })))
          const nextData = mutationTree.data
          currentDataRef.current = nextData
          setFolderDataPure(nextData)

          if (dragIds.length > 0) await loadDirectory(destination.data)
        }
      })
    }

    if (isExist) {
      onShowConfirm({
        title: `Replace ${_dragNode.data.name}?`,
        onConfirm: () => void move(true),
      })
    } else {
      onShowConfirm({
        title: `Move ${_dragNode.data.name}?`,
        onConfirm: () => void move(),
      })
    }
  }

  const handleSelect = (nodes: { data: IFile }[] | null | undefined) => {
    if (nodes && nodes.length > 0 && nodes[0]?.data) {
      onSelect?.(nodes[0].data)
    }
  }

  const renderFileNode = (
    nodeProps: Pick<FileNodeComponentProps, 'dragHandle' | 'node' | 'style' | 'tree'>,
    isRoot: boolean,
    isStickyRoot = false,
    isRootSuppressed = false,
  ) => (
    <FileNode
      {...nodeProps}
      getCurrentFolderData={getCurrentFolderData}
      canInsertIntoDirectory={canInsertIntoDirectory}
      setFolderData={commitFolderData}
      refreshDirectory={refreshDirectory}
      onFocusActiveFile={focusActiveFile}
      onOpen={onOpen}
      isRoot={isRoot}
      onShowConfirm={onShowConfirm}
      onRequestDelete={onRequestDelete ? requestDelete : undefined}
      onShowInputConfirm={onShowInputConfirm}
      onShowContextMenu={onShowContextMenu}
      getFileObject={getFileObject}
      getFileObjectByPath={getFileObjectByPath}
      setFileObject={setFileObject}
      setFileObjectByPath={setFileObjectByPath}
      deletePathEntry={deletePathEntry}
      getFileIdsByPathPrefix={getFileIdsByPathPrefix}
      moveFileObjectsByPathPrefix={moveFileObjectsByPathPrefix}
      deleteFileObjectsByPathPrefix={deleteFileObjectsByPathPrefix}
      createFile={createFile}
      updateFile={updateFile}
      fileTreeHandler={fileTreeHandler}
      disableFileOperations={disableFileOperations}
      iconButtonComponent={iconButtonComponent as FC<any>}
      renderNodeIcon={renderNodeIcon}
      renderNodePrefix={renderNodePrefix}
      renderNodeName={renderNodeName}
      rootActions={rootActions}
      isLoading={loadingDirIds.has(nodeProps.node.id)}
      isEmpty={
        nodeProps.node.isOpen &&
        !!nodeProps.node.data.path &&
        loadedDirPaths.has(nodeProps.node.data.path) &&
        nodeProps.node.data.children?.length === 0
      }
      isStickyRoot={isStickyRoot}
      isRootSuppressed={isRootSuppressed}
    />
  )

  const renderTreeNode = (nodeProps: NodeRendererProps<IFile>) => {
    const isRoot = nodeProps.node.id === rootId
    if (isRoot) {
      treeRef.current = nodeProps.tree
      fileTreeHandler.rootTree = nodeProps.tree
      fileTreeHandler.updateTreeView = (params) => {
        fileTreeHandler.rootTree?.update({ data: params.data })
        setFolderDataPure(params.data)
      }
      fileTreeHandler.clearLoadedDirsCache = () => {
        loadedDirsCacheVersionRef.current += 1
        loadedDirsRef.current.clear()
        loadingDirsRef.current.clear()
        refreshDirsRef.current.clear()
        setLoadingDirIds((current) => (current.size === 0 ? current : new Set()))
        setLoadedDirPaths((current) => (current.size === 0 ? current : new Set()))
      }
    }
    return renderFileNode(nodeProps, isRoot, false, isRoot && showStickyRoot)
  }

  if (data.length === 0) return null

  return (
    <FileTreeNodeRendererContext.Provider value={renderTreeNode}>
      <FillFlexParent>
        {(dimens) => {
          const treeElement = (
            <Tree
              key={rootId}
              ref={setTreeApi}
              {...dimens}
              data={data}
              childrenAccessor={childrenAccessor}
              dndRootElement={dndRootElement}
              disableDrag={disableDrag}
              initialOpenState={initialOpenState}
              openByDefault={false}
              selection={activeId}
              indent={indentSize}
              rowHeight={rowHeight}
              rowClassName='mf-file-tree-item'
              renderRow={stickyRoot || onOpen ? FileTreeRow : undefined}
              disableMultiSelection
              onSelect={handleSelect}
              onMove={onMove}
              onToggle={onToggle}
              onScroll={stickyRoot ? handleScroll : undefined}
              onContextMenu={(e) => {
                if (disableFileOperations) return

                const items: ContextMenuItem[] = []
                const workspaceRoot = data[0]
                if (workspaceRoot) {
                  items.push(
                    {
                      label: 'New File',
                      value: 'new_file',
                      handler: () => {
                        const newData = {
                          id: `pending-${Date.now()}`,
                          name: '',
                          kind: 'pending_new_file',
                        } as IFile
                        treeRef.current?.open(workspaceRoot.id)
                        tree.create({
                          parentId: workspaceRoot.id,
                          data: newData,
                        })
                        setFolderDataPure(tree.data)
                      },
                    },
                    {
                      label: 'New Folder',
                      value: 'new_folder',
                      handler: () => {
                        const newData = {
                          id: `pending-${Date.now()}`,
                          name: '',
                          kind: 'pending_new_folder',
                          children: [],
                        } as IFile
                        treeRef.current?.open(workspaceRoot.id)

                        tree.create({
                          parentId: workspaceRoot.id,
                          data: newData,
                        })
                        setFolderDataPure(tree.data)
                      },
                    },
                  )
                }

                if (items.length === 0) return
                onShowContextMenu({
                  x: e.clientX,
                  y: e.clientY,
                  items,
                })
              }}
            >
              {FileTreeNodeRenderer}
            </Tree>
          )

          if (!stickyRoot) return (
            <FileTreeRowStateContext.Provider value={fileTreeRowState}>
              {treeElement}
            </FileTreeRowStateContext.Provider>
          )

          const rootTree = treeRef.current
          const rootNode = rootTree?.get(rootId ?? null)
          return (
            <FileTreeRowStateContext.Provider value={fileTreeRowState}>
              <FileTreeStickyViewport style={dimens}>
                {treeElement}
                {showStickyRoot && rootNode && rootTree ? (
                  <FileTreeStickyRoot
                    aria-label={rootNode.data.name}
                    data-mf-file-tree-sticky-layer=''
                    role='tree'
                    style={{ height: rowHeight }}
                  >
                    <div
                      aria-expanded={rootNode.isInternal ? rootNode.isOpen : undefined}
                      aria-label={rootNode.data.name}
                      aria-level={1}
                      aria-selected={rootNode.isSelected}
                      className='mf-file-tree-item'
                      data-mf-file-tree-sticky-item=''
                      onClick={rootNode.handleClick}
                      onKeyDown={(event) => {
                        if (event.target !== event.currentTarget) return

                        if (event.key === 'Enter' || event.key === ' ') {
                          event.preventDefault()
                          event.stopPropagation()
                          rootNode.select()
                          rootNode.activate()
                          rootNode.toggle()
                          return
                        }

                        if (event.key === 'ArrowLeft') {
                          event.preventDefault()
                          event.stopPropagation()
                          if (rootNode.isInternal && rootNode.isOpen) rootNode.close()
                          return
                        }

                        if (event.key === 'ArrowRight') {
                          event.preventDefault()
                          event.stopPropagation()
                          if (rootNode.isInternal && !rootNode.isOpen) rootNode.open()
                          return
                        }

                        if (event.key === 'Home' || event.key === 'ArrowUp') {
                          event.preventDefault()
                          event.stopPropagation()
                          revealRoot()
                          rootTree.focus(rootNode)
                        }
                      }}
                      role='treeitem'
                      style={{ height: '100%' }}
                      tabIndex={0}
                    >
                      {renderFileNode(
                        {
                          dragHandle: undefined,
                          node: rootNode,
                          style: { paddingLeft: 0 },
                          tree: rootTree,
                        },
                        true,
                        true,
                      )}
                    </div>
                  </FileTreeStickyRoot>
                ) : null}
              </FileTreeStickyViewport>
            </FileTreeRowStateContext.Provider>
          )
        }}
      </FillFlexParent>
    </FileTreeNodeRendererContext.Provider>
  )
}

type FileTreeRowProps = RowRendererProps<IFile> & Partial<FileTreeRowState>

export function FileTreeRow({
  attrs,
  children,
  innerRef,
  node,
  revealRoot: revealRootOverride,
  rootId: rootIdOverride,
  suppressRoot: suppressRootOverride,
}: FileTreeRowProps) {
  const rowState = useContext(FileTreeRowStateContext)
  const revealRoot = revealRootOverride ?? rowState.revealRoot
  const rootId = rootIdOverride ?? rowState.rootId
  const suppressRoot = suppressRootOverride ?? rowState.suppressRoot
  const isRoot = node.id === rootId
  const suppressed = isRoot && suppressRoot
  const canOpen = Boolean(rowState.onOpen) && node.data.kind === 'file' && !node.isEditing

  return (
    <div
      {...attrs}
      ref={innerRef}
      aria-label={suppressed ? node.data.name : attrs['aria-label']}
      data-mf-file-tree-root-row={isRoot || undefined}
      data-mf-file-tree-root-row-suppressed={suppressed || undefined}
      onClick={(event) => {
        node.handleClick(event)
        if (canOpen && !event.defaultPrevented) {
          // With "open notes in the same tab" the click replaces the note on screen; otherwise
          // every note gets its own tab. The middle button always asks for a new tab.
          rowState.onOpen?.(node.data, { mode: rowState.openInSameTab ? 'replace' : 'permanent' })
        }
      }}
      onAuxClick={(event) => {
        // Middle click opens the note in its own tab, the way browsers open links.
        if (!canOpen || event.button !== 1) return
        event.preventDefault()
        rowState.onOpen?.(node.data, { mode: 'permanent' })
      }}
      onMouseDown={(event) => {
        if (event.button === 1) event.preventDefault()
      }}
      onDoubleClick={(event) => {
        if (!canOpen || event.defaultPrevented) return
        rowState.onOpen?.(node.data, { mode: 'permanent' })
      }}
      onKeyDown={(event) => {
        if (!canOpen || event.target !== event.currentTarget || (event.key !== 'Enter' && event.key !== ' ')) return
        event.preventDefault()
        event.stopPropagation()
        node.select()
        // Space and Enter both open the note in its own tab.
        rowState.onOpen?.(node.data, { mode: 'permanent' })
      }}
      onFocus={(event) => {
        if (suppressed) revealRoot?.()
        event.stopPropagation()
      }}
    >
      {children}
    </div>
  )
}

export default memo(FileTree)
