import HeadingNode from './HeadingTreeNode';

export enum TraverseResult {
  Continue = 1,
  NoChildren = 2,
  Stop = 3,
}

export interface IHeadingData {
  depth: number; // h2 => 2, h3 => 3, etc
  value: string;
  /**
   * Optional chapter text supplied by the heading source.
   * Use null to hide the chapter for this heading.
   */
  chapter?: string | null;
  id: string;
  htmlNode: HTMLElement | null;
  onClick?: (headingItem: IHeadingData) => void;
}

export class HeadingTree {
  private root?: HeadingNode;

  private offsetCacheVersion: number;

  constructor(headings: IHeadingData[]) {
    // Make depths of nodes relative
    const minDepth = headings.reduce((depth, heading) => Math.min(depth, heading.depth), Infinity);
    const offsetCacheVersion = 0;

    const headingNodes: HeadingNode[] = headings.map((h, i) => {
      return new HeadingNode({
        h,
        depth: h.depth - minDepth,
        key: i,
        offsetCacheVersion,
        chapter: '0',
      });
    });

    const nodeStack: HeadingNode[] = [
      new HeadingNode({
        h: { depth: -1, value: '', id: '', htmlNode: null },
        depth: -1,
        key: -1,
        offsetCacheVersion,
        chapter: '0',
      }),
    ]; // init with root node
    const siblingCounts = new Map<HeadingNode, Map<number, number>>()
    headingNodes.forEach((node) => {
      while (nodeStack.length && nodeStack[nodeStack.length - 1].depth >= node.depth) {
        nodeStack.pop();
      }

      nodeStack[nodeStack.length - 1].children.push(node);
      node.parent = nodeStack[nodeStack.length - 1];

      let countsByDepth = siblingCounts.get(node.parent);
      if (!countsByDepth) {
        countsByDepth = new Map()
        siblingCounts.set(node.parent, countsByDepth)
      }
      const siblingNumber = (countsByDepth.get(node.depth) ?? 0) + 1
      countsByDepth.set(node.depth, siblingNumber)

      let diff = node.depth - Math.max(node.parent.depth, 0);
      if (diff === 0) {
        node.chapter = String(siblingNumber);
      } else if (diff === 1) {
        node.chapter = `${node.parent.chapter}.${siblingNumber}`;
      } else {
        node.chapter = node.parent.chapter;

        while (diff >= 1) {
          node.chapter += '.';
          if (diff === 1) {
            node.chapter += siblingNumber;
          } else {
            node.chapter += 0;
          }
          diff--;
        }
      }

      if (typeof node.h.chapter === 'string') {
        node.chapter = node.h.chapter;
      }

      nodeStack.push(node);
    });

    this.root = nodeStack[0];
    this.offsetCacheVersion = offsetCacheVersion;
  }

  getRoot() {
    return this.root;
  }

  markOffsetCacheStale() {
    this.offsetCacheVersion++;
  }

  traverseInPreorder(f: (h: HeadingNode) => TraverseResult) {
    const visitChildren = (h: HeadingNode): TraverseResult => {
      for (const child of h.children) {
        if (visit(child) === TraverseResult.Stop) {
          return TraverseResult.Stop;
        }
      }
      return TraverseResult.Continue;
    };

    const visit = (h: HeadingNode): TraverseResult => {
      const result = f(h);
      if (result === TraverseResult.Stop) {
        return TraverseResult.Stop;
      }
      if (result === TraverseResult.NoChildren) {
        return TraverseResult.Continue;
      }
      return visitChildren(h);
    };

    if (this.root) {
      for (const child of this.root.children) {
        if (visit(child) === TraverseResult.Stop) {
          break;
        }
      }
    }
  }
}
